entries[145167] = { ["name"] = "Großer Nudelwagenbausatz", ["text"] = "Wirken in 2 sek.\nReagenzien:\nGegrilltes Tigersteak (10), Gebratene Karotten (10), Verwirbelte Nebelsuppe (10), Garnelenklößchen (10), Wildgeflügelbraten (10), Ginsengtee (10)\n(5)\n90\nBenutzen: Baut einen Nudelwagen auf, um Nudelsuppe zu verkaufen!\n\nJede Suppe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 250 erhöht.\n\"Enthält alles, was Ihr benötigt, um Euren eigenen großen Nudelwagen zu bauen und bis zu 25 Portionen zu verkaufen.\"" }
entries[145169] = { ["name"] = "Nudelwagen Deluxe", ["text"] = "5 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nBaut einen Nudelwagen Deluxe auf, um Nudelsuppe Deluxe zu verkaufen!\n\nJede Nudelsuppe Deluxe stellt im Verlauf von 20 Sek. 300000 Gesundheit und 300000 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein für Euch nützlicher Wert wird 1 Stunde lang um 275 erhöht." }
