entries[145416] = { ["name"] = "Vergiften", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nFinishing-Move, der sofort Naturschaden proportional zu den auf dem Ziel bestehenden Combopunkten verursacht. Nach Einsatz von 'Vergiften' ist Eure Chance, das Ziel zu vergiften, um 15% erhöht. Dieser Effekt hält eine Sekunde plus jeweils eine weitere Sekunde pro Combopunkt lang an." }
