entries[145418] = { ["name"] = "Zerhäckseln", ["text"] = "25 Energie 100 Meter Reichweite\nSofort\nFinishing-Move, der alle Combopunkte eines nahen Ziels verbraucht, um Euer Nahkampfangriffstempo um 40% zu erhöhen. Hält pro Combopunkt länger an." }
entries[145419] = { ["name"] = "Tödliches Gift", ["text"] = "100 Meter Reichweite\nSofort\nSind Eure Waffen vergiftet, besteht eine Chance, dass Ihr Zielen, die bereits mit Eurem tödlichen Gift vergiftet sind, 9250 bis 10750 Naturschaden zufügt." }
entries[145420] = { ["name"] = "Tödliches Gift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. ( 748 * 4) Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort 390 Naturschaden." }
entries[145421] = { ["name"] = "Tödliches Gift", ["text"] = "Wirken in 3 sek.\nBenötigt Einhändige Nahkampfwaffe\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 12 Sek. lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. 80000 Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort 9250 bis 10750 Naturschaden.\n(Procchance: 30%)" }
entries[145422] = { ["name"] = "Dolchfächer", ["text"] = "35 Energie\nSofort\nWirbelt sofort herum und schleudert allen Zielen im Umkreis von 10 Metern einen Klingenregen entgegen, der 46250 bis 53750 körperlichen Schaden verursacht. Dieser Angriff hat eine Chance, Eure Ziele zu einer normalen Rate zu vergiften. Gewährt 46250 bis 53750 Combopunkte, wenn Ihr ein Ziel trefft, auf dem bereits Eure Combopunkte aktiv sind." }
entries[145423] = { ["name"] = "Verstohlenheit", ["text"] = "Sofort 6 sek. Abklingzeit\nVerbirgt Euch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden. Hält an, bis die Aktion abgebrochen wird." }
entries[145424] = { ["name"] = "Fieser Trick", ["text"] = "40 Energie 10 Meter Reichweite\nSofort\nBenötigt Verstohlenheit\nBetäubt das Ziel 4 Sek. lang. Muss im Verstohlenheitsmodus sein. Gewährt 2 Combopunkte [ Mantel und Degen : und lässt Euch hinter dem Ziel erscheinen ]." }
entries[145425] = { ["name"] = "Schattenschritt", ["text"] = "100 Meter Reichweite\nSofort\nLässt Euch in die Schatten tauchen, um hinter dem Gegner zu erscheinen. Danach wird Euer Bewegungstempo 2 Sek. lang um 70% erhöht." }
