entries[145433] = { ["name"] = "Arkane Aufladung", ["text"] = "Sofort\nEine arkane Aufladung, erzeugt von 'Arkanschlag', 'Arkane Geschosse' und 'Arkane Explosion'. Wird von 'Arkanbeschuss' und 'Hervorrufung' verbraucht:\n\nArkanschlag\nErzeugt eine Aufladung.\nPro Aufladung werden der Schaden von 'Arkanschlag' um 50% und die Manakosten um 150% erhöht.\n\nArkane Geschosse\nErzeugt eine Aufladung.\nPro Aufladung wird der Schaden von 'Arkane Geschosse' um 50% erhöht.\n\nArkane Explosion\nFrischt bestehende Aufladungen auf und hat eine Chance von 30%, eine Aufladung zu erzeugen, wenn mindestens ein Ziel getroffen wird.\n\nArkanbeschuss\nVerbraucht alle Aufladungen.\nPro Aufladung wird der Schaden von 'Arkanbeschuss' um 50% erhöht. Außerdem fügt er pro Aufladung 1 zusätzlichem Ziel 50% Schaden zu.\n\nHervorrufung\nVerbraucht alle Aufladungen.\nPro Aufladung wird die Manaerzeugung von 'Hervorrufung' um 25% erhöht.\n\nBis zu 4-mal stapelbar. Hält 10 Sek. lang an." }
entries[145434] = { ["name"] = "Arkanschlag", ["text"] = "8% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nÜberzieht einen Gegner mit Energie und verursacht so 809 Arkanschaden. Erzeugt eine Arkane Aufladung.\n\nPro Arkaner Aufladung wird der Schaden von 'Arkanschlag' um 50% und seine Manakosten um 150% erhöht." }
entries[145435] = { ["name"] = "Arkane Geschosse", ["text"] = "60 Meter Reichweite\nKanalisiert\nFeuert im Verlauf von 2 Sek. fünf Wellen arkaner Geschosse auf den Gegner ab, die pro Welle 231 Arkanschaden verursachen. Erzeugt eine Arkane Aufladung.\n\nPro Arkaner Aufladung wird der Schaden von 'Arkane Geschosse' um 50% erhöht.\n\nJeder Eurer Schaden verursachenden Zauber gewährt eine Chance, 'Arkane Geschosse' auszulösen. Maximal 2 Aufladungen." }
entries[145436] = { ["name"] = "Arkane Geschosse", ["text"] = "40 Meter Reichweite\nKanalisiert (Wirken in 2 sek.)\nFeuert im Verlauf von 2 Sek. fünf Wellen arkaner Geschosse auf den Gegner ab, die pro Welle 231 Arkanschaden verursachen. Erzeugt eine Arkane Aufladung.\n\nPro Arkaner Aufladung wird der Schaden von 'Arkane Geschosse' um 50% erhöht." }
entries[145437] = { ["name"] = "Arkanbeschuss", ["text"] = "4% von Grundmana 40 Meter Reichweite\nSofort 3 sek. Abklingzeit\nSchleudert mehrere Geschosse aus Arkanenergie auf das gegnerische Ziel, die 50000 Arkanschaden verursachen. Der Zauber trifft auch 4 zusätzliche Gegner in der Nähe und fügt ihnen 50% Schaden zu. Verbraucht alle arkanen Aufladungen.\n\nPro arkaner Aufladung wird der Schaden von 'Arkanbeschuss' um 50% erhöht." }
