entries[145530] = { ["name"] = "Gegenzauber", ["text"] = "40 Meter Reichweite\nSofort 24 sek. Abklingzeit\nKontert das Zauberwirken des Gegners und verhindert so 3 Sek. lang, dass ein Zauber dieser Art gewirkt werden kann." }
