entries[145547] = { ["name"] = "Elektrifizierter Boden", ["text"] = "Wirken in 2.5 sek.\nElektrifiziert den Boden und fügt allen Gegnern im Umkreis von 6 Metern um den Zaubernden 140000 Naturschaden zu." }
