entries[145549] = { ["name"] = "Giftblitztotem", ["text"] = "Sofort\nBeschwört ein Giftblitztotem zu Füßen des Zaubernden, das 15 Sek. lang bestehen bleibt und zufällige Spielercharaktere mit Giftblitzen angreift." }
entries[145550] = { ["name"] = "Gedankenstachel", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nSticht auf die Gedanken eines Gegners ein und verursacht 200% Waffenschaden als Schattenfrost." }
entries[145551] = { ["name"] = "Schattenflamme", ["text"] = "Wirken in 2 sek.\nZiele in einem kegelförmigen Bereich von bis zu 10 Metern vor dem Zaubernden erleiden 129500 bis 150500 Schattenflammenschaden und sind 3 Sek. lang desorientiert." }
