entries[145553] = { ["name"] = "Bestechung", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nÜbernimmt durch Bestechung die Kontrolle über einen Gegner, erhöht 30 Sek. lang den verursachten Schaden um 200% und die Gesundheit um 200%. Dieser Effekt wird beendet, wenn die Gesundheit des Ziels unter 50% sinkt." }
