entries[145555] = { ["name"] = "Mächtige Kettenheilung", ["text"] = "50 Meter Reichweite\nWirken in 2.5 sek.\nHeilt einen Verbündeten um 10% seiner maximalen Gesundheit und springt auf einen Verbündeten in der Nähe über, wobei sich die Heilung pro Sprung um 50% erhöht. Wirkt sich auf bis zu 5 Ziele aus." }
entries[145556] = { ["name"] = "Heilungsflut", ["text"] = "Sofort\nHeilt Verbündete innerhalb von 8 Metern alle 3 Sek. um 20% ihrer maximalen Gesundheit." }
entries[145557] = { ["name"] = "Heilungsflut", ["text"] = "Wirken in 1 sek.\nHeilt Verbündete innerhalb von 8 Metern alle 3 Sek. um 20% ihrer maximalen Gesundheit." }
